.acct label{display:block;font-size:13px;color:#60a5fa;margin-bottom:6px;font-weight:600;}
.acct select{background:#1e293b;color:#fff;border:1px solid #334155;border-radius:6px;padding:8px 12px;font-size:14px;min-width:200px;outline:none;cursor:pointer;}
.acct select:focus{border-color:#3b82f6;}
.tblwrap{border:1px solid #1e293b;border-radius:8px;overflow:auto;max-height:calc(100vh - 220px);}
table{width:100%;border-collapse:collapse;font-size:14px;}
thead th{position:sticky;top:0;background:#0f172a;color:#cbd5e1;font-weight:700;text-align:right;padding:13px 18px;white-space:nowrap;border-bottom:2px solid #1e293b;z-index:1;}
thead th:first-child{text-align:left;}
tbody td{padding:12px 18px;text-align:right;color:#e2e8f0;white-space:nowrap;}
tbody td:first-child{text-align:left;color:#f1f5f9;}
tbody tr:nth-child(odd){background:#1e293b;}
tbody tr:nth-child(even){background:#0f172a;}
.empty{padding:28px;text-align:center;color:#64748b;font-style:italic;}
.skel{padding:22px;color:#94a3b8;}
::-webkit-scrollbar{width:10px;height:10px;background:#0f172a;}
::-webkit-scrollbar-thumb{background:#1e293b;border-radius:4px;border:2px solid #0f172a;}
*{scrollbar-color:#1e293b #0f172a;scrollbar-width:thin;}

