import React, { useState, useMemo, useEffect } from "https://esm.sh/react@18.2.0";
import ReactDOM from "https://esm.sh/react-dom@18.2.0";

const MONTHS = ["January","February","March","April","May","June","July","August","September","October","November","December"];

function fmtMonth(v){
  const s = String(v || "").slice(0, 10);
  const parts = s.split("-");
  if (parts.length < 2) return s;
  const y = parts[0], m = parseInt(parts[1], 10);
  return (MONTHS[m - 1] || "") + " " + y;
}
function fmtCur(n){
  return "$" + Number(n || 0).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}
function fmtNum(n){
  return Number(n || 0).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}
function titleCase(s){
  s = String(s || "").toLowerCase();
  return s.charAt(0).toUpperCase() + s.slice(1);
}

function aggregate(rows, acct){
  const byMonth = {};
  (rows || []).forEach(function(r){
    if (acct !== "ALL" && r.utility_type !== acct) return;
    const k = String(r.month || "").slice(0, 10);
    if (!k) return;
    if (!byMonth[k]) byMonth[k] = { month: k, dist: 0, supply: 0, cons: 0 };
    byMonth[k].dist += Number(r.distribution_cost || 0);
    byMonth[k].supply += Number(r.supply_cost || 0);
    byMonth[k].cons += Number(r.consumption || 0);
  });
  return Object.keys(byMonth).map(function(k){ return byMonth[k]; })
    .sort(function(a, b){ return b.month.localeCompare(a.month); });
}

function AccountSelect({ utils, value, onChange }) {
  return React.createElement("div", { className: "acct" },
    React.createElement("label", null, "Select Accounts"),
    React.createElement("select", { value: value, onChange: function(e){ onChange(e.target.value); } },
      [React.createElement("option", { key: "ALL", value: "ALL" }, "All Accounts")].concat(
        utils.map(function(u){
          return React.createElement("option", { key: u, value: u }, "All " + titleCase(u) + " Accounts");
        })
      )
    )
  );
}

function App(){
  const [model, setModel] = useState(appsmith.model || {});
  const [costAcct, setCostAcct] = useState("ALL");
  const [consAcct, setConsAcct] = useState("ALL");

  useEffect(function(){
    const update = function(){ setModel({ ...(appsmith.model || {}) }); };
    update();
    if (typeof appsmith.onModelChange === "function") appsmith.onModelChange(update);
    const id = setInterval(update, 400);
    return function(){ clearInterval(id); };
  }, []);

  const rows = (model && model.rows) || [];
  const utils = useMemo(function(){
    const set = {};
    rows.forEach(function(r){ if (r.utility_type) set[r.utility_type] = true; });
    return Object.keys(set).sort();
  }, [rows]);

  const cost = useMemo(function(){ return aggregate(rows, costAcct); }, [rows, costAcct]);
  const cons = useMemo(function(){ return aggregate(rows, consAcct); }, [rows, consAcct]);

  if (model && model.isLoading) {
    return React.createElement("div", { className: "skel" }, "Loading metrics...");
  }

  const costTable = React.createElement("div", { className: "tblwrap" },
    React.createElement("table", null,
      React.createElement("thead", null, React.createElement("tr", null,
        React.createElement("th", null, "Month"),
        React.createElement("th", null, "Total Cost"),
        React.createElement("th", null, "Distribution Cost"),
        React.createElement("th", null, "Supply Cost")
      )),
      React.createElement("tbody", null,
        cost.length === 0
          ? React.createElement("tr", null, React.createElement("td", { className: "empty", colSpan: 4 }, "No cost history"))
          : cost.map(function(r){
              return React.createElement("tr", { key: r.month },
                React.createElement("td", null, fmtMonth(r.month)),
                React.createElement("td", null, fmtCur(r.dist + r.supply)),
                React.createElement("td", null, fmtCur(r.dist)),
                React.createElement("td", null, fmtCur(r.supply))
              );
            })
      )
    )
  );

  const consTable = React.createElement("div", { className: "tblwrap" },
    React.createElement("table", null,
      React.createElement("thead", null, React.createElement("tr", null,
        React.createElement("th", null, "Month"),
        React.createElement("th", null, "Consumption"),
        React.createElement("th", null, "Unit Cost")
      )),
      React.createElement("tbody", null,
        cons.length === 0
          ? React.createElement("tr", null, React.createElement("td", { className: "empty", colSpan: 3 }, "No consumption history"))
          : cons.map(function(r){
              const unit = r.cons > 0 ? (r.dist + r.supply) / r.cons : 0;
              return React.createElement("tr", { key: r.month },
                React.createElement("td", null, fmtMonth(r.month)),
                React.createElement("td", null, fmtNum(r.cons)),
                React.createElement("td", null, r.cons > 0 ? fmtCur(unit) : "-")
              );
            })
      )
    )
  );

  return React.createElement("div", { className: "wrap" },
    React.createElement("div", { className: "col" },
      React.createElement("h3", null, "Cost History"),
      React.createElement(AccountSelect, { utils: utils, value: costAcct, onChange: setCostAcct }),
      costTable
    ),
    React.createElement("div", { className: "col" },
      React.createElement("h3", null, "Consumption History"),
      React.createElement(AccountSelect, { utils: utils, value: consAcct, onChange: setConsAcct }),
      consTable
    )
  );
}

ReactDOM.render(React.createElement(App, null), document.getElementById("root"));

